import java.util.*;
public class cf3082C {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String input = scanner.nextLine();
        scanner.close();
        String[] parts = input.split(" ");
        int baseW = Integer.parseInt(parts[0]);
        int numberM = Integer.parseInt(parts[1]);

        int tempNumber = numberM;
        int maxExponent = (int) (Math.log(tempNumber) / Math.log(baseW));
        int arraySize = maxExponent + 2;
        int[] digitArray = new int[arraySize];

        for (int power = maxExponent; power >= 0; power--) {
            digitArray[power] = (int) ((tempNumber / Math.pow(baseW, power)) % baseW);
        }

        boolean isSequenceValid = true;
        for (int i = 0; i <= maxExponent; i++) {
            if (digitArray[i] >= baseW) {
                digitArray[i] %= baseW;
                digitArray[i + 1]++;
            }
            if (digitArray[i] != 0 && digitArray[i] != 1) {
                digitArray[i]++;
            }
            if (digitArray[i] >= baseW) {
                digitArray[i] %= baseW;
                digitArray[i + 1]++;
            }
        }

        for (int i = 0; i < arraySize; i++) {
            if (digitArray[i] != 0 && digitArray[i] != 1) {
                isSequenceValid = false;
                break;
            }
        }
        System.out.println(isSequenceValid ? "YES" : "NO");
    }
}
